/bin/bash -lc "python - <<'PY'
import pathlib,re
for f in sorted(pathlib.Path('.').glob('*.txt')):
 s=f.read_text(); page='?'; lines=s.splitlines(); hits=[]
 for i,l in enumerate(lines):
  m=re.search(r'--- page (\\d+) ---',l)
  if m: page=m.group(1)
  if re.search(r'California|governed|Governing|GOVERNING|laws of|law of',l,re.I):
   hits.append(f'p. {page}: '+ ' '.join(lines[max(0,i-1):min(len(lines),i+3)]))
 print('\\nFILE:',f.name, '\\n'+'\\n'.join(hits))
PY"

